import * as React from "react";

export type StreamLiveDotIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function StreamLiveDotIcon({ size = 20, ...props }: StreamLiveDotIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="6" width="17" height="12" rx="2" /><circle cx="12" cy="12" r="2.5" /><path d="M6.5 9h.5M17 14.5h.5" />
    </svg>
  );
}
